insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('dph-pm-note-101','Pharmacy','Diploma in Pharmacy','note','free',1201,'{"title":"Principles and Functions of Pharmaceutical Management","english":"Pharmaceutical management is the process of planning, organizing, staffing, directing, coordinating and controlling pharmacy resources and services to achieve safe, effective and efficient medicine supply. Core functions include setting objectives, allocating resources, supervising work, maintaining communication, monitoring performance and improving service quality. Good management balances patient needs, medicine quality, availability, affordability and regulatory compliance.","nepali":"Pharmaceutical management भनेको सुरक्षित, प्रभावकारी र व्यवस्थित औषधि आपूर्ति तथा pharmacy सेवा सञ्चालन गर्न planning, organizing, staffing, directing, coordinating र controlling गर्ने प्रक्रिया हो। यसको मुख्य काममा उद्देश्य निर्धारण, स्रोत बाँडफाँट, कामको supervision, सञ्चार, कार्यसम्पादन अनुगमन र सेवा गुणस्तर सुधार पर्छन्। राम्रो व्यवस्थापनले बिरामीको आवश्यकता, औषधिको गुणस्तर, उपलब्धता, लागत र कानुनी पालना सन्तुलन गर्छ।"}'::jsonb,true),
('dph-pm-note-102','Pharmacy','Diploma in Pharmacy','note','free',1202,'{"title":"Medicine Procurement and Supplier Management","english":"Procurement ensures that quality-assured medicines are obtained in the right quantity, at the right time and at a reasonable total cost from reliable, authorized suppliers. The process may include estimating needs, preparing specifications, obtaining quotations or using an approved tender process, evaluating suppliers, placing orders, receiving goods and checking documentation, quantity, batch number, expiry and product condition. Follow the institution’s procurement policy and current public procurement and medicine regulations where applicable.","nepali":"Procurement ले भरपर्दो तथा अधिकृत supplier बाट गुणस्तर सुनिश्चित भएका औषधि सही मात्रा, सही समयमा र उचित कुल लागतमा उपलब्ध गराउँछ। यसमा आवश्यकता अनुमान, specification तयार, quotation वा स्वीकृत tender प्रक्रिया, supplier मूल्याङ्कन, order, सामान प्राप्ति तथा कागजात, मात्रा, batch number, expiry र अवस्थाको जाँच पर्छ। संस्थाको procurement policy तथा लागू सार्वजनिक खरिद र औषधिसम्बन्धी नियम पालना गर्नुपर्छ।"}'::jsonb,true),
('dph-pm-note-103','Pharmacy','Diploma in Pharmacy','note','free',1203,'{"title":"Inventory Control and Stock Management Techniques","english":"Inventory control maintains adequate stock while minimizing stock-outs, overstocking, expiry and wastage. Essential records include stock cards or electronic ledgers, receipts, issues, balances, batch numbers and expiry dates. Reorder level helps trigger replenishment before stock runs out; safety stock provides a buffer against variation in demand or delivery time. ABC analysis classifies items by annual consumption value, while VEN analysis classifies them by vital, essential and non-essential importance. FEFO should guide issue of dated products.","nepali":"Inventory control ले औषधि अभाव, अत्यधिक stock, expiry र नोक्सानी घटाउँदै पर्याप्त stock कायम गर्छ। आवश्यक अभिलेखमा stock card वा electronic ledger, प्राप्ति, वितरण, बाँकी मौज्दात, batch number र expiry date पर्छन्। Reorder level ले stock सकिनुअघि पुनः खरिद सुरु गर्न संकेत गर्छ; safety stock ले माग वा delivery ढिलाइको जोखिममा buffer दिन्छ। ABC analysis ले वार्षिक खपत मूल्यका आधारमा र VEN analysis ले vital, essential र non-essential महत्त्वका आधारमा वर्गीकरण गर्छ। म्याद भएका सामान वितरण गर्दा FEFO अपनाउनुपर्छ।"}'::jsonb,true),
('dph-pm-note-104','Pharmacy','Diploma in Pharmacy','note','free',1204,'{"title":"Pharmacy Budgeting, Human Resources and Supervision","english":"A budget is a financial plan for a defined period. Pharmacy budgets may cover medicine procurement, staffing, equipment, storage, utilities and other operating costs. Budget preparation uses service needs, past consumption, expected changes, prices and available funds. Human-resource management includes defining roles, ensuring suitable staffing, orientation, training, fair duty allocation, supervision and performance feedback. Staff should understand their responsibilities, limits of practice, safety procedures and reporting lines.","nepali":"Budget निश्चित अवधिका लागि तयार गरिएको आर्थिक योजना हो। Pharmacy budget मा औषधि खरिद, कर्मचारी, उपकरण, भण्डारण, utilities र अन्य सञ्चालन खर्च पर्न सक्छन्। Budget बनाउँदा सेवाको आवश्यकता, विगतको खपत, अपेक्षित परिवर्तन, मूल्य र उपलब्ध रकम विचार गरिन्छ। Human-resource management मा जिम्मेवारी निर्धारण, उपयुक्त कर्मचारी व्यवस्था, orientation, तालिम, न्यायोचित duty बाँडफाँट, supervision र performance feedback पर्छन्। कर्मचारीले आफ्नो जिम्मेवारी, कार्यक्षेत्रको सीमा, सुरक्षा प्रक्रिया र reporting line बुझ्नुपर्छ।"}'::jsonb,true),
('dph-pm-note-105','Pharmacy','Diploma in Pharmacy','note','free',1205,'{"title":"Quality Assurance, Documentation and Pharmacy Audits","english":"Quality assurance is a planned system to ensure that pharmacy processes and services consistently meet defined standards. It includes written standard operating procedures (SOPs), staff training, appropriate storage, temperature monitoring where required, cleaning, documentation, complaint handling, recall procedures and corrective and preventive action (CAPA). Audits compare actual practice and records with approved standards, identify gaps and support improvement. Records should be accurate, legible, dated, traceable and protected from unauthorized alteration.","nepali":"Quality assurance भनेको pharmacy का प्रक्रिया र सेवाले तोकिएका मापदण्ड निरन्तर पूरा गरेको सुनिश्चित गर्ने योजनाबद्ध प्रणाली हो। यसमा लिखित SOP, कर्मचारी तालिम, उचित भण्डारण, आवश्यक तापक्रम निगरानी, सफाइ, अभिलेख, गुनासो व्यवस्थापन, recall प्रक्रिया र corrective तथा preventive action (CAPA) पर्छन्। Audit ले वास्तविक काम र अभिलेखलाई स्वीकृत मापदण्डसँग तुलना गरी कमी पहिचान र सुधारमा सहयोग गर्छ। अभिलेख सही, पढ्न मिल्ने, मितिसहित, traceable र अनधिकृत परिवर्तनबाट सुरक्षित हुनुपर्छ।"}'::jsonb,true),
('dph-pm-mcq-101','Pharmacy','Diploma in Pharmacy','mcq','free',1201,'{"question":"Which set best represents the core management functions?","translation":"व्यवस्थापनका मुख्य कार्य कुन समूहले सही रूपमा देखाउँछ?","options":["Planning, organizing, staffing, directing and controlling","Only purchasing and selling","Only prescribing and diagnosing","Only advertising"],"correctIndex":0,"explanation":"These are core functions used to organize and control pharmacy resources and services.","explanationNe":"यी planning, organizing, staffing, directing र controlling pharmacy स्रोत तथा सेवा व्यवस्थापनका मुख्य कार्य हुन्।"}'::jsonb,true),
('dph-pm-mcq-102','Pharmacy','Diploma in Pharmacy','mcq','free',1202,'{"question":"The main objective of medicine procurement is to obtain:","translation":"औषधि खरिदको मुख्य उद्देश्य के हो?","options":["Quality-assured medicines in the right quantity and time","The largest possible quantity regardless of need","Only the cheapest unverified products","Medicines without records"],"correctIndex":0,"explanation":"Procurement aims for quality, appropriate quantity, timely availability and reasonable total cost.","explanationNe":"Procurement को उद्देश्य गुणस्तरयुक्त औषधि उपयुक्त मात्रा र समयमा उचित लागतमा उपलब्ध गराउनु हो।"}'::jsonb,true),
('dph-pm-mcq-103','Pharmacy','Diploma in Pharmacy','mcq','free',1203,'{"question":"What does a reorder level indicate?","translation":"Reorder level ले के संकेत गर्छ?","options":["When replenishment should be initiated","When staff should take leave","The retail price of a medicine","The expiry date only"],"correctIndex":0,"explanation":"Reorder level is the stock level at which replenishment should be initiated to prevent stock-out.","explanationNe":"Stock सकिन नदिन पुनः खरिद प्रक्रिया सुरु गर्नुपर्ने मौज्दात स्तरलाई reorder level भनिन्छ।"}'::jsonb,true),
('dph-pm-mcq-104','Pharmacy','Diploma in Pharmacy','mcq','free',1204,'{"question":"ABC analysis classifies inventory mainly according to:","translation":"ABC analysis ले inventory लाई मुख्यतः कुन आधारमा वर्गीकरण गर्छ?","options":["Annual consumption value","Colour of packaging","Medicine taste","Alphabetical order only"],"correctIndex":0,"explanation":"ABC analysis groups items by their annual consumption value to focus management attention.","explanationNe":"ABC analysis ले वार्षिक खपत मूल्यका आधारमा सामान वर्गीकरण गरी व्यवस्थापनको ध्यान केन्द्रित गर्छ।"}'::jsonb,true),
('dph-pm-mcq-105','Pharmacy','Diploma in Pharmacy','mcq','free',1205,'{"question":"In VEN analysis, the letter V stands for:","translation":"VEN analysis मा V ले के जनाउँछ?","options":["Vital","Variable","Verified","Volume"],"correctIndex":0,"explanation":"VEN classifies medicines as Vital, Essential and Non-essential.","explanationNe":"VEN analysis मा Vital, Essential र Non-essential गरी वर्गीकरण गरिन्छ।"}'::jsonb,true),
('dph-pm-mcq-106','Pharmacy','Diploma in Pharmacy','mcq','free',1206,'{"question":"Safety stock is maintained mainly to:","translation":"Safety stock मुख्यतः किन राखिन्छ?","options":["Buffer against unexpected demand or delivery delays","Increase expiry","Replace all stock records","Avoid stock monitoring"],"correctIndex":0,"explanation":"Safety stock helps protect against uncertainty in demand and replenishment lead time.","explanationNe":"माग वा सामान आउन लाग्ने समय अनिश्चित हुँदा अभाव नहोस् भनेर safety stock राखिन्छ।"}'::jsonb,true),
('dph-pm-mcq-107','Pharmacy','Diploma in Pharmacy','mcq','free',1207,'{"question":"A pharmacy budget is best described as:","translation":"Pharmacy budget लाई कसरी परिभाषित गरिन्छ?","options":["A financial plan for a defined period","A list of expired medicines","A patient diagnosis sheet","A supplier advertisement"],"correctIndex":0,"explanation":"A budget estimates income or available funds and planned expenditure over a period.","explanationNe":"Budget निश्चित अवधिको उपलब्ध रकम र योजनाबद्ध खर्चको आर्थिक योजना हो।"}'::jsonb,true),
('dph-pm-mcq-108','Pharmacy','Diploma in Pharmacy','mcq','free',1208,'{"question":"Which document gives step-by-step instructions for a routine pharmacy process?","translation":"Pharmacy को नियमित कामका चरणबद्ध निर्देशन कुन कागजातले दिन्छ?","options":["Standard Operating Procedure (SOP)","Advertisement leaflet","Personal diary","Price poster"],"correctIndex":0,"explanation":"An SOP documents the approved steps for performing a process consistently.","explanationNe":"SOP ले कुनै प्रक्रिया समान र स्वीकृत तरिकाले गर्नुपर्ने चरणहरू लेखेर राख्छ।"}'::jsonb,true),
('dph-pm-mcq-109','Pharmacy','Diploma in Pharmacy','mcq','free',1209,'{"question":"The main purpose of a pharmacy audit is to:","translation":"Pharmacy audit को मुख्य उद्देश्य के हो?","options":["Compare practice with standards and identify improvements","Punish every staff member","Hide documentation gaps","Increase unnecessary purchases"],"correctIndex":0,"explanation":"Audits assess compliance, identify gaps and support corrective improvement.","explanationNe":"Audit ले मापदण्ड पालना भए नभएको जाँच्छ, कमी पहिचान गर्छ र सुधारमा सहयोग गर्छ।"}'::jsonb,true),
('dph-pm-mcq-110','Pharmacy','Diploma in Pharmacy','mcq','free',1210,'{"question":"Which is an important feature of a reliable pharmacy record?","translation":"विश्वसनीय pharmacy record को महत्त्वपूर्ण विशेषता कुन हो?","options":["Accurate, dated and traceable information","Undated entries","Erasable undocumented changes","Missing batch details where required"],"correctIndex":0,"explanation":"Records should be accurate, dated, legible and traceable to support accountability and safety.","explanationNe":"जवाफदेहिता र सुरक्षाका लागि अभिलेख सही, मितिसहित, पढ्न मिल्ने र traceable हुनुपर्छ।"}'::jsonb,true),
('dph-pm-mock-101','Pharmacy','Diploma in Pharmacy','mock','free',1201,'{"question":"Define pharmaceutical management and list its major functions.","answer":"Pharmaceutical management is the process of managing pharmacy resources and services to ensure safe and efficient medicine supply. Major functions include planning, organizing, staffing, directing, coordinating and controlling.","answerNe":"Pharmaceutical management भनेको सुरक्षित र प्रभावकारी औषधि आपूर्ति सुनिश्चित गर्न pharmacy का स्रोत तथा सेवा व्यवस्थापन गर्ने प्रक्रिया हो। मुख्य कार्य planning, organizing, staffing, directing, coordinating र controlling हुन्।"}'::jsonb,true),
('dph-pm-mock-102','Pharmacy','Diploma in Pharmacy','mock','free',1202,'{"question":"Describe the key steps in a medicine procurement process.","answer":"Estimate needs, prepare product specifications, identify approved suppliers, obtain quotations or follow the approved procurement method, evaluate offers, place orders, receive and inspect products, verify documents and record stock.","answerNe":"आवश्यकता अनुमान गर्ने, product specification तयार गर्ने, स्वीकृत supplier पहिचान गर्ने, quotation वा स्वीकृत खरिद विधि अपनाउने, प्रस्ताव मूल्याङ्कन गर्ने, order दिने, सामान प्राप्त गरी जाँच्ने, कागजात पुष्टि गर्ने र stock अभिलेख राख्ने।"}'::jsonb,true),
('dph-pm-mock-103','Pharmacy','Diploma in Pharmacy','mock','free',1203,'{"question":"Differentiate ABC analysis and VEN analysis.","answer":"ABC analysis classifies items according to annual consumption value (A high, B medium, C low). VEN analysis classifies items according to clinical importance as Vital, Essential and Non-essential. They can be used together to support prioritization.","answerNe":"ABC analysis ले वार्षिक खपत मूल्यका आधारमा A (उच्च), B (मध्यम) र C (कम) वर्ग बनाउँछ। VEN analysis ले clinical महत्त्वका आधारमा Vital, Essential र Non-essential वर्ग बनाउँछ। प्राथमिकता निर्धारण गर्न दुवै सँगै प्रयोग गर्न सकिन्छ।"}'::jsonb,true),
('dph-pm-mock-104','Pharmacy','Diploma in Pharmacy','mock','free',1204,'{"question":"Explain the role of a budget and human-resource management in a pharmacy.","answer":"A budget plans and controls expenditure for medicines, staff, equipment and operations. Human-resource management ensures appropriate staffing, clear roles, orientation, training, supervision, fair duty allocation and performance feedback.","answerNe":"Budget ले औषधि, कर्मचारी, उपकरण र सञ्चालन खर्चको योजना तथा नियन्त्रण गर्छ। Human-resource management ले उपयुक्त कर्मचारी, स्पष्ट भूमिका, orientation, तालिम, supervision, न्यायोचित duty बाँडफाँट र performance feedback सुनिश्चित गर्छ।"}'::jsonb,true),
('dph-pm-mock-105','Pharmacy','Diploma in Pharmacy','mock','free',1205,'{"question":"What is quality assurance in pharmacy? Mention five activities that support it.","answer":"Quality assurance is a planned system to ensure services and processes meet defined standards. Activities include SOPs, staff training, proper storage and temperature monitoring, accurate documentation, audits, complaint and recall handling, and corrective and preventive actions.","answerNe":"Quality assurance भनेको सेवा तथा प्रक्रियाले तोकिएका मापदण्ड पूरा गरेको सुनिश्चित गर्ने योजनाबद्ध प्रणाली हो। यसका गतिविधिमा SOP, कर्मचारी तालिम, उचित भण्डारण तथा तापक्रम निगरानी, सही अभिलेख, audit, गुनासो तथा recall व्यवस्थापन र corrective/preventive action पर्छन्।"}'::jsonb,true)
